/* @lc app=leetcode id=2338 lang=kotlin */
class Solution { fun idealArrays(n: Int, maxi: Int): Int = minOf(n, 14).let { maxK -> Array(maxi + 1) { IntArray(maxK + 1) }.apply { (1..maxi).forEach { i -> this[i][1] = 1 } }.apply { (1 until maxK).forEach { k -> (1..maxi).forEach { i -> (2 * i..maxi step i).forEach { j -> this[j][k + 1] = (this[j][k + 1] + this[i][k]) % 1000000007 } } } }.let { dp -> LongArray(maxK + 1).apply { this[1] = 1 }.apply { (2..maxK).forEach { k -> this[k] = this[k - 1] * (n - k + 1) % 1000000007 * java.math.BigInteger.valueOf(k.toLong() - 1).modInverse(java.math.BigInteger.valueOf(1000000007)).toLong() % 1000000007 } }.let { comb -> (1..maxi).map { i -> (1..maxK).map { k -> dp[i][k].toLong() * comb[k] % 1000000007 }.sum() % 1000000007 }.sum().let { (it % 1000000007).toInt() } } } } }